From 7e802f64e6e54e7908690b8f0f7c7c651ab52a1c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:03:59 +0100
Subject: [PATCH] plugins/highlightwindow: allow raising windows without hiding
 others

Highlighting windows always hid every other window, which some users
find too disruptive. Add a highlightWindows overload that can instead
show the highlighted windows in front, keeping panels and popups above.

BUG: 461431
---
 .../highlightwindow/highlightwindow.cpp       | 57 ++++++++++++++++++-
 src/plugins/highlightwindow/highlightwindow.h |  5 ++
 2 files changed, 60 insertions(+), 2 deletions(-)

diff --git a/src/plugins/highlightwindow/highlightwindow.cpp b/src/plugins/highlightwindow/highlightwindow.cpp
index 63f000c705..d692fc3157 100644
--- a/src/plugins/highlightwindow/highlightwindow.cpp
+++ b/src/plugins/highlightwindow/highlightwindow.cpp
@@ -51,6 +51,11 @@ static bool isHighlightWindow(EffectWindow *window)
 }

 void HighlightWindowEffect::highlightWindows(const QStringList &windows)
+{
+    highlightWindows(windows, true);
+}
+
+void HighlightWindowEffect::highlightWindows(const QStringList &windows, bool hideOthers)
 {
     QList<EffectWindow *> effectWindows;
     effectWindows.reserve(windows.count());
@@ -61,16 +66,23 @@ void HighlightWindowEffect::highlightWindows(const QStringList &windows)
             effectWindows.append(effectWindow);
         }
     }
+    m_hideOthers = hideOthers;
     highlightWindows(effectWindows);
 }

 void HighlightWindowEffect::slotWindowAdded(EffectWindow *w)
 {
-    if (!m_highlightedWindows.isEmpty()) {
+    if (m_highlightedWindows.isEmpty()) {
+        return;
+    }
+    if (m_hideOthers) {
         if (isHighlightWindow(w)) {
             const quint64 animationId = startGhostAnimation(w); // this window is not currently highlighted
             complete(animationId);
         }
+    } else if (!isHighlightWindow(w) && !w->isDesktop()) {
+        effects->setElevatedWindow(w, true);
+        m_elevatedWindows.append(w);
     }
 }

@@ -78,6 +90,7 @@ void HighlightWindowEffect::slotWindowDeleted(EffectWindow *w)
 {
     m_animations.remove(w);
     m_highlightedWindows.removeOne(w);
+    m_elevatedWindows.removeOne(w);
 }

 void HighlightWindowEffect::prepareHighlighting()
@@ -90,12 +103,49 @@ void HighlightWindowEffect::prepareHighlighting()

         if (isHighlighted(window)) {
             startHighlightAnimation(window);
-        } else if (window->isVisible()) {
+        } else if (window->isVisible() && m_hideOthers) {
             startGhostAnimation(window);
         } else {
             startRevertAnimation(window);
         }
     }
+
+    deelevateWindows();
+    if (!m_hideOthers) {
+        elevateWindows();
+    }
+}
+
+void HighlightWindowEffect::elevateWindows()
+{
+    // Bring the highlighted windows to the front, but keep panels, popups and the like above them
+    const QList<EffectWindow *> windows = effects->stackingOrder();
+    auto it = std::find_if(windows.begin(), windows.end(), [this](EffectWindow *window) {
+        return isHighlighted(window);
+    });
+    for (EffectWindow *window : windows) {
+        if (window->isDeleted() || !isHighlighted(window)) {
+            continue;
+        }
+        effects->setElevatedWindow(window, true);
+        m_elevatedWindows.append(window);
+    }
+    for (; it != windows.end(); ++it) {
+        EffectWindow *window = *it;
+        if (window->isDeleted() || isHighlightWindow(window) || window->isDesktop()) {
+            continue;
+        }
+        effects->setElevatedWindow(window, true);
+        m_elevatedWindows.append(window);
+    }
+}
+
+void HighlightWindowEffect::deelevateWindows()
+{
+    for (EffectWindow *window : std::as_const(m_elevatedWindows)) {
+        effects->setElevatedWindow(window, false);
+    }
+    m_elevatedWindows.clear();
 }

 void HighlightWindowEffect::finishHighlighting()
@@ -109,6 +159,8 @@ void HighlightWindowEffect::finishHighlighting()
         startRevertAnimation(window);
     }

+    deelevateWindows();
+
     // Sanity check, ideally, this should never happen.
     if (!m_animations.isEmpty()) {
         for (quint64 &animationId : m_animations) {
@@ -192,6 +244,7 @@ bool HighlightWindowEffect::perform(Feature feature, const QVariantList &argumen
     if (arguments.size() != 1) {
         return false;
     }
+    m_hideOthers = true;
     highlightWindows(arguments.first().value<QList<EffectWindow *>>());
     return true;
 }
diff --git a/src/plugins/highlightwindow/highlightwindow.h b/src/plugins/highlightwindow/highlightwindow.h
index ea0ac71a45..5e4b8205c1 100644
--- a/src/plugins/highlightwindow/highlightwindow.h
+++ b/src/plugins/highlightwindow/highlightwindow.h
@@ -31,6 +31,7 @@ public:
     bool perform(Feature feature, const QVariantList &arguments) override;
     void reconfigure(ReconfigureFlags flags) override;
     Q_SCRIPTABLE void highlightWindows(const QStringList &windows);
+    Q_SCRIPTABLE void highlightWindows(const QStringList &windows, bool hideOthers);

 public Q_SLOTS:
     void slotWindowAdded(KWin::EffectWindow *w);
@@ -46,12 +47,16 @@ private:
     void prepareHighlighting();
     void finishHighlighting();
     void highlightWindows(const QList<KWin::EffectWindow *> &windows);
+    void elevateWindows();
+    void deelevateWindows();

     QList<EffectWindow *> m_highlightedWindows;
     QHash<EffectWindow *, quint64> m_animations;
     QEasingCurve m_easingCurve;
     std::chrono::milliseconds m_fadeDuration;
     float m_ghostOpacity = 0;
+    bool m_hideOthers = true;
+    QList<EffectWindow *> m_elevatedWindows;
 };

 } // namespace
